  "documentation": {
    "weeklyExperimentLog": "\n# Weekly Experiment Log \u2014 Week 1\n\n## Work completed\n- Inspected PM2.5 distribution, missingness, and temporal patterns.\n- Selected six pooled cities: Bengaluru, Chennai, Delhi, Hyderabad, Lucknow, and Patna.\n- Selected Mumbai and Guwahati for the planned held-out-city analysis.\n- Created daily calendars, next-day targets, lag features, and rolling means.\n- Excluded Xylene and PM10 using the training-only missingness threshold.\n- Created chronological training, validation, and test splits.\n- Saved the modelling table to Google Drive.\n\n## Data checks\n- Modelling table: 11,037 rows and 22 columns.\n- Training: 7,751 rows; validation: 2,188 rows; test: 1,098 rows.\n- Missing next-day targets: 0.\n- Duplicate city-target-date rows: 0.\n\n## Decisions and limitations\n- Missing targets were not imputed.\n- Missing predictors are retained for later preprocessing.\n- Test performance has not been evaluated.\n- Descriptive patterns do not establish causation.\n\n## Next steps\n- Continue baseline and model-development preparation.\n- Fit preprocessing on training data only.\n- Select models using validation data.\n- Reserve the test set for final evaluation.\n"
  }
